import { Buffer } from "node:buffer";
export default function authorize({ headers, body, expectedAuthorization }) {
  const expected = typeof expectedAuthorization === "string" ? expectedAuthorization.trim() : "";
  const p = /^Basic ([A-Za-z0-9+/]+={0,2})$/.exec(expected),
    secret = p ? Buffer.from(p[1], "base64").toString("utf8") : "";
  if (!p || !/^[^:]+:.+$/.test(secret) || /[\r\n]/.test(secret))
    throw Error("Configure a Basic authorization secret");
  const entries = Object.entries(headers || {}).filter(
      ([k]) => k.toLowerCase() === "authorization",
    ),
    match =
      entries.length === 1 && typeof entries[0][1] === "string"
        ? /^Basic +([A-Za-z0-9+/]+={0,2})$/i.exec(entries[0][1].trim())
        : null,
    actual = match ? Buffer.from(match[1], "base64").toString("utf8") : "";
  let diff = secret.length ^ actual.length;
  for (let i = 0; i < Math.max(secret.length, actual.length); i++)
    diff |= (secret.charCodeAt(i) || 0) ^ (actual.charCodeAt(i) || 0);
  if (diff)
    return { accepted: false, statusCode: 401, response: { error: "Unauthorized" }, request: {} };
  return { accepted: true, statusCode: 200, response: { accepted: true }, request: body };
}

